-- 基本情報技術者試験
INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'kihon-joho', '基本情報技術者試験', 'IT・情報', '{"short_name":"基本情報","authority":{"name":"独立行政法人 情報処理推進機構(IPA)","url":"https://www.ipa.go.jp/shiken/kubun/fe.html"},"exam":{"eligibility":"受験資格を定めた記載は、IPAの試験要綱・公式サイトで確認できなかった。年齢や学歴の制限を課す記述も見当たらない。「誰でも受験できる」という明文が無いため、ここでは断定していない。","fee_yen":7500,"format":"CBT(コンピュータを使った試験)。科目Aと科目Bの2部構成で、科目Aは知識を問う四肢択一の60問、科目Bはプログラミングなどの技能を問う多肢選択の20問。採点は素点ではなくIRT(項目応答理論。解答の正誤パターンから統計的に評価点を算出する方式)による。","questions":80,"duration_minutes":190,"passing_criteria":"科目A・科目Bそれぞれ1,000点満点中、評価点600点以上であること。両方の科目で基準を満たす必要があり、片方だけ高得点でも合格にならない。","frequency":"CBT方式で年間を通じて随時実施される。身体の不自由などでCBTを利用できない人向けに、年2回(前期・後期)のペーパー方式の特別措置試験がある。","result_announcement":"受験した月の翌月に発表される(令和8年度の例では5月受験分が6月22日の正午)。IPAのサイトに合格者の受験番号が掲示され、受験者マイページでも確認できる。掲示は実施月から半年間で終了する。","source_urls":{"eligibility":"https://www.ipa.go.jp/shiken/kubun/fe.html","fee_yen":"https://www.ipa.go.jp/shiken/2021/jukenryou20210716.html","format":"https://www.ipa.go.jp/shiken/syllabus/rcu1hd00000141gq-att/youkou_ver5_6.pdf","questions":"https://www.ipa.go.jp/shiken/syllabus/rcu1hd00000141gq-att/youkou_ver5_6.pdf","duration_minutes":"https://www.ipa.go.jp/shiken/syllabus/rcu1hd00000141gq-att/youkou_ver5_6.pdf","passing_criteria":"https://www.ipa.go.jp/shiken/syllabus/rcu1hd00000141gq-att/youkou_ver5_6.pdf","frequency":"https://www.ipa.go.jp/shiken/mousikomi/cbt_sg_fe.html","result_announcement":"https://www.ipa.go.jp/shiken/mousikomi/cbt_sg_fe.html"},"subjects":["科目A(知識) 60問・90分","科目B(技能) 20問・100分"],"duration_note":"科目A 90分+科目B 100分の合計190分。科目Aの終了後に最長10分の休憩があり、拘束時間は最大200分になる。","fee_note":"2022年4月実施の試験から、5,700円が7,500円に改定された。","questions_note":"科目A 60問と科目B 20問の合計を questions としている。2科目は別々に受験時間が区切られる。","retrieved_at":"2026-07-26","format_note":"出典の試験要綱はVer.5.6(2026年10月の試験から適用)。現行のVer.5.5と基本情報技術者試験の記載内容は同一であることを確認済み。"},"related":[{"slug":"it-passport","reason":"同じIPAが実施する入門級の試験。基本情報はその上位に位置づけられる"}],"schedule_url":"https://www.ipa.go.jp/shiken/mousikomi/cbt_sg_fe.html","verification":{"collected_by":"researcher(一次ソースのみ)+ PM(Fable)","verified_by":"fact-checker(独立に一次ソースを再取得。PDFはローカル抽出で本文照合)","verified_at":"2026-07-26","result":"統計5年度分は推移表と完全一致。合格基準(各1,000点満点・600点・IRT)も要綱p.15で確認。「受験資格の記載は確認できなかった」という記述自体を検証し、要綱・FAQ・概要ページのいずれにも記載が無いことを確認済み(正当)。修正は軽微3件: 特別措置試験の月(出典に無いため削除)、休憩を含む拘束時間の注記、参照した要綱の版の注記。"},"notes":"確認できなかった項目: (1) 受験資格。試験要綱に受験資格の章が無く、「制限なし」の明文も見つからなかった。制限を課す記述も無い。断定を避けて「確認できなかった」と記載している。(2) 合格発表の「翌月22日」が全月共通の規則かどうか。公表されている個別月の日付例から一般化はしていない。","public_note":"数値はすべてIPAの公表資料に基づきます。合格には科目A・科目Bの両方で1,000点満点中600点以上が必要です。"}', '{"official_stats":{"unit":"全国集計(年度単位・IPA発表)","series":[{"year":"令和7年度","applicants":172217,"examinees":147186,"passers":56370,"pass_rate":38.3,"source_url":"https://www.ipa.go.jp/shiken/reports/hjuojm000000ll0f-att/suii_hyo.pdf","retrieved_at":"2026-07-26"},{"year":"令和6年度","applicants":157259,"examinees":133732,"passers":54501,"pass_rate":40.8,"source_url":"https://www.ipa.go.jp/shiken/reports/hjuojm000000ll0f-att/suii_hyo.pdf","retrieved_at":"2026-07-26"},{"year":"令和5年度","applicants":140774,"examinees":121611,"passers":57278,"pass_rate":47.1,"source_url":"https://www.ipa.go.jp/shiken/reports/hjuojm000000ll0f-att/suii_hyo.pdf","retrieved_at":"2026-07-26"},{"year":"令和4年度(旧制度)","applicants":117624,"examinees":101620,"passers":38033,"pass_rate":37.4,"source_url":"https://www.ipa.go.jp/shiken/reports/hjuojm000000ll0f-att/suii_hyo.pdf","retrieved_at":"2026-07-26"},{"year":"令和3年度(旧制度)","applicants":97577,"examinees":85428,"passers":34734,"pass_rate":40.7,"source_url":"https://www.ipa.go.jp/shiken/reports/hjuojm000000ll0f-att/suii_hyo.pdf","retrieved_at":"2026-07-26"}],"source_url":"https://www.ipa.go.jp/shiken/reports/hjuojm000000ll0f-att/suii_hyo.pdf","retrieved_at":"2026-07-26","notes":"IPAの推移表(令和8年4月21日現在)から取得した。2023年4月(令和5年度)に科目A/B・IRT採点へ全面変更されており、令和4年度以前とは採点方式が異なる。連続した推移として比較できないため、年度名に(旧制度)を付けて区別している。全5年度で合格者数÷受験者数が公表合格率と一致することを検算済み。","unit_labels":{"applicants":"応募者数","examinees":"受験者数(実際に受験した人数)","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"2023年4月に試験制度が大きく変わりました(科目A/B化・採点方式の変更)。令和4年度以前の合格率は採点方式が異なるため、そのまま比較はできません。"}}')
ON CONFLICT DO NOTHING;

-- 登録販売者試験
INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'touroku-hanbaisha', '登録販売者試験', '医療・福祉', '{"short_name":"登録販売者","authority":{"name":"各都道府県(全国集計は厚生労働省)","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/newpage_57810.html"},"exam":{"eligibility":"学歴・実務経験の要件はない(平成27年度の試験から要件が撤廃された)。","fee_yen":null,"format":"マークシート方式の筆記試験。全120問を、120分×2部の計240分で解く。出題は厚生労働省の「試験問題作成に関する手引き」に基づくが、試験問題そのものは実施する都道府県(または広域連合)ごとに異なる。","questions":120,"duration_minutes":240,"passing_criteria":"総得点の7割以上で、かつ試験項目ごとにも一定割合以上の正答が必要。項目ごとの下限は北海道では「4割以上」と明記されているが、都道府県により異なる場合があるため、受験する自治体の要項で確認が必要。","frequency":"年1回、都道府県(または関西広域連合などの広域連合)ごとに実施される。全国一斉の試験日はなく、日程は地域によって異なる。","result_announcement":"実施主体のウェブサイトに合格者の受験番号が掲示される。合格者には「合格通知書」が後日郵送されるが、不合格者への通知はない(関西広域連合の受験案内による)。","source_urls":{"eligibility":"https://www.hokeniryo.metro.tokyo.lg.jp/anzen/iyaku/tourokushiken/tourokuqa/r6shiken","format":"https://www.kouiki-kansai.jp/material/files/group/12/20260518tohan_juken_annai.pdf","questions":"https://www.kouiki-kansai.jp/material/files/group/12/20260518tohan_juken_annai.pdf","duration_minutes":"https://www.kouiki-kansai.jp/material/files/group/12/20260518tohan_juken_annai.pdf","passing_criteria":"https://www.pref.hokkaido.lg.jp/hf/iyk/258176.html","frequency":"https://www.pref.hokkaido.lg.jp/hf/iyk/258176.html","result_announcement":"https://www.kouiki-kansai.jp/material/files/group/12/20260518tohan_juken_annai.pdf"},"subjects":["医薬品に共通する特性と基本的な知識 20問","人体の働きと医薬品 20問","主な医薬品とその作用 40問","薬事関係法規・制度 20問","医薬品の適正使用・安全対策 20問"],"fee_note":"受験手数料は実施する都道府県で異なるため、単一の金額を掲載していない。例として北海道は18,200円、関西広域連合(滋賀・京都・大阪・兵庫・奈良・和歌山・徳島)は12,800円。","retrieved_at":"2026-07-26"},"related":[{"slug":"eisei-kanri-1","reason":"同じく就労に直結する免許系の資格"}],"schedule_url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/newpage_57810.html","schedule_url_note":"試験日程は都道府県ごとに公表される。厚労省ページは制度全体の案内。","verification":{"collected_by":"researcher(一次ソースのみ)+ PM(Fable)","verified_by":"fact-checker(独立に一次ソースを再取得。PDFはローカル抽出で本文照合)","verified_at":"2026-07-26","result":"統計4年度分は全件一致。修正2件+表現5件を反映した。(1) 厚労省の制度ページURLが404だった(3か所)。検証側が正しいページを特定し差し替えた。(2) 受験資格に禁止語「誰でも」を使っていた(掟3-7)。同じ事実を基本情報のページでは断定回避しており、基準の不一致でもあった。ほか、出典に無い記述(登録後の実務の仕組み・実施月の範囲・難易度差の断定)を削るか言い換えた。"},"notes":"確認できなかった項目: (1) 令和7年度の全国集計(厚労省の一覧ページに未掲載であることは確認済み。未公表とは断定していない)。(2) 項目別の正答率下限が全国共通かどうか(北海道の「各項目4割以上」の明記のみ確認)。(3) 実施月の全国的な範囲。いずれも推測で埋めていない。","public_note":"試験は都道府県ごとに実施され、手数料・日程・合格基準の細部が地域で異なります。申込前に必ず受験する自治体の要項をご確認ください。"}', '{"official_stats":{"unit":"全国集計(厚生労働省発表・延べ人数)","series":[{"year":"令和6年度","applicants":null,"examinees":54526,"passers":25459,"pass_rate":46.7,"source_url":"https://www.mhlw.go.jp/content/11121000/001487496.pdf","retrieved_at":"2026-07-26"},{"year":"令和5年度","applicants":null,"examinees":52214,"passers":22814,"pass_rate":43.7,"source_url":"https://www.mhlw.go.jp/content/11121000/001487495.pdf","retrieved_at":"2026-07-26"},{"year":"令和4年度","applicants":null,"examinees":55606,"passers":24707,"pass_rate":44.4,"source_url":"https://www.mhlw.go.jp/content/11121000/001487494.pdf","retrieved_at":"2026-07-26"},{"year":"令和3年度","applicants":null,"examinees":61070,"passers":30082,"pass_rate":49.3,"source_url":"https://www.mhlw.go.jp/content/11121000/001487493.pdf","retrieved_at":"2026-07-26"}],"source_url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/newpage_57810.html","retrieved_at":"2026-07-26","notes":"厚生労働省が公表する年度別の試験実施状況(都道府県別一覧)の「年度計」から取得した。受験者数・合格者数は延べ人数で、同一人が複数の都道府県で受験した分を含むと資料に明記されている。全4年度で合格者数÷受験者数が公表合格率と一致することを検算済み。令和7年度の集計は、厚労省の一覧ページに掲載が無いことを独立検証で確認した(未公表とは断定していない)。掲載され次第追加する。","unit_labels":{"applicants":"申込者数(未公表)","examinees":"受験者数(延べ人数)","passers":"合格者数(延べ人数)","pass_rate":"合格率(%)"},"public_note":"受験者数・合格者数は延べ人数です。この試験は同じ年に複数の都道府県で受験できるため、同じ人が2回以上数えられている場合があります。また令和6年度の合格率は北海道62.3%〜沖縄24.5%と地域差が大きいですが、試験問題は都道府県ごとに異なるため、地域間の単純比較はできません。"}}')
ON CONFLICT DO NOTHING;

